/// `{param, plural, one{# day} other{# days}}` for [locale].
String _dd(String param, String locale) => _kDurationIcu['dur_days']![locale]!.replaceFirst('{count,', '{$param,');

/// `{param, plural, one{# day left} other{# days left}}` for [locale].
String _dLeft(String param, String locale) => _kDurationIcu['dur_days_left']![locale]!.replaceFirst('{count,', '{$param,');

const _kPillFree = {'en': 'free', 'pl': 'darmowe', 'tr': 'ücretsiz', 'de': 'gratis', 'cs': 'zdarma', 'sk': 'zadarmo', 'uk': 'безкоштовно', 'be': 'бясплатна', 'lt': 'nemokamai', 'ru': 'бесплатно'};

const _kAllLocales = ['en', 'pl', 'tr', 'de', 'cs', 'sk', 'uk', 'be', 'lt', 'ru'];

/// One ICU duration message for every locale.
Map<String, String> _durAll(String Function(String param, String locale) f, String param, [String prefix = '', String suffix = '']) =>
    {for (final l in _kAllLocales) l: '$prefix${f(param, l)}$suffix'};

